package dev.smpcristalix.pvpcombat.api;import dev.smpcristalix.pvpcombat.service.*;import org.bukkit.entity.Player;import java.util.UUID;public final class PvPCombatApiImpl implements PvPCombatApi{private final ShardService shards;private final CombatService combat;private final StatsService stats;public PvPCombatApiImpl(ShardService s,CombatService c,StatsService t){shards=s;combat=c;stats=t;}public void giveShards(Player p,int a){shards.give(p,a);}public boolean isInCombat(Player p){return combat.inCombat(p);}public PlayerStatsSnapshot getStats(UUID u){var p=stats.profile(u);return new PlayerStatsSnapshot(p.damageLevel(),stats.healthHearts(p),p.speedLevel(),p.satietyLevel(),p.abilityLevel());}}
